// expect: exit 7
// screen: 0 a=3 b=7
void swap(int *p, int *q)
{
    int t = *p;
    *p = *q;
    *q = t;
}
int main(void)
{
    int a = 7, b = 3;
    cls();
    swap(&a, &b);
    printf("a=%d b=%d\n", a, b);
    return b;
}
